function Invoke-ThcEnum { $domain=$args ; ((Invoke-RestMethod -Method Get -Uri "https://ip.thc.org/api/v1/subdomains/download?domain=$domain" ) -replace "^subdomain$","" | Sort-Object -Unique | Out-String -Stream) -replace "^subdomain$","" }
function Invoke-AnubisEnum { $domain=$args ; Invoke-RestMethod -Method Get -Uri "https://anubisdb.com/anubis/subdomains/$domain" | Sort-Object -Unique | Out-String -Stream }
function Invoke-GoogleDnsReq { $domain=$args[0] ; $type=$args[1] ; Invoke-RestMethod -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36' -Uri "https://dns.google/resolve?name=$domain&rtype=$type" }                  
function Invoke-CfDnsReq { $domain=$args[0] ; $type=$args[1] ; Invoke-RestMethod -UserAgent 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/138.0.0.0 Safari/537.36' -Headers @{"Accept"="application/dns-json"} -Uri "https://one.one.one.one/dns-query?name=$domain&rtype=$type" }
function Invoke-AzMap { $domain=$args[0] ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://azmap.dev/api/tenant?domain=$domain" }
function Get-AzTenantDomainOIDC { $domain=$args[0] ; Invoke-RestMethod -Method Get -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" -Uri "https://login.microsoftonline.com/$domain/v2.0/.well-known/openid-configuration" }
function Invoke-GitRecon { gh api -H "Accept: application/vnd.github+json" -H "X-GitHub-Api-Version: 2026-03-10"  /search/code?q=$args | ConvertFrom-Json | Select-Object -ExpandProperty items | Select-Object -ExpandProperty url | % { Invoke-RestMethod -Method Get -Uri "$_" -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:152.0) Gecko/20100101 Firefox/152.0"| Select-Object -ExpandProperty download_url -ErrorAction SilentlyContinue } | Out-String -Stream | Out-File $args-gitrecon.log -Append ; gh api  -H "Accept: application/vnd.github+json" -H "X-GitHub-Api-Version: 2026-03-10"  /search/code?q=$args | ConvertFrom-Json | Select-Object -ExpandProperty items | Select-Object -ExpandProperty url | % { Invoke-RestMethod -Method Get -Uri "$_" -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:152.0) Gecko/20100101 Firefox/152.0"| Select-Object -ExpandProperty download_url -ErrorAction SilentlyContinue | % { Invoke-RestMethod -Method Get -Uri "$_" -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:152.0) Gecko/2010010 Firefox/152.0" | Out-String -Stream | Out-File $args-srcCode-gitrecon.log -Append } } }
function Invoke-Jsluice { Invoke-RestMethod -Method Get -Uri "$args" -UserAgent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:147.0) Gecko/20100101 Firefox/147.0" | jsluice urls -j -R "$args" | awk -F '"' '{ print $4 }' }
function Invoke-Katana { katana -u $args[0] -depth 5 -concurrency 15 -parallelism 15 -js-crawl -jsluice -crawl-duration 90 -timeout 120 -retry 2 -v -hl -headless -kf all -o $args[1] }
function Export-BbotUrls { Import-Csv $args | Where-Object -Property "Event type" -EQ URL | Select-Object -ExpandProperty "Event data" -Unique }
function Invoke-Gowitness { gowitness scan file -f $args -t 20 --chrome-user-agent "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:150.0) Gecko/20100101 Firefox/150.0" --write-db }
